import{_ as a,o as e,c as r,aj as l}from"./chunks/framework.Cn87zHeG.js";const p=JSON.parse('{"title":"产品版本与开发路径","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/editions.md","filePath":"getting-started/editions.md"}'),o={name:"getting-started/editions.md"};function i(n,t,h,d,s,m){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="产品版本与开发路径" tabindex="-1">产品版本与开发路径 <a class="header-anchor" href="#产品版本与开发路径" aria-label="Permalink to &quot;产品版本与开发路径&quot;">​</a></h1><p>H1 提供标准版和智能版。智能版在标准版 RK3576 主控的基础上增加 NVIDIA 计算板，为有更高算力需求的应用提供开发平台。</p><table tabindex="0"><thead><tr><th>对比项</th><th>H1 标准版</th><th>H1 智能版</th></tr></thead><tbody><tr><td>计算平台</td><td>RK3576</td><td>RK3576 + NVIDIA 计算板</td></tr><tr><td>开发方向</td><td>通过 SDK 接入机器人基础功能，开发控制与应用程序</td><td>在标准版基础上，利用 NVIDIA 计算板开展有更高算力需求的应用开发</td></tr></tbody></table><p>两种产品共用 <strong>ROS 2 Jazzy + 原生 Zenoh</strong> 开发环境。开始前建议<a href="./communication.html#choose">查看并更新固件</a>，再按 <a href="./communication.html">ROS 2 通信配置</a>接入机器人；硬件与应用场景按上表选择。</p><h2 id="standard" tabindex="-1">H1 标准版 <a class="header-anchor" href="#standard" aria-label="Permalink to &quot;H1 标准版 {#standard}&quot;">​</a></h2><p>标准版采用 RK3576 主控。现有 SDK 文档介绍了底盘、升降、头部、机械臂等控制接口，以及 SLAM、导航等功能。</p><p>建议按以下顺序开始：</p><ol><li><a href="./ros2-installation.html">安装 ROS 2 Jazzy</a>，准备开发电脑。</li><li>完成 <a href="./communication.html">ROS 2 通信配置与检查</a>，再按<a href="./../example/">示例仓库与使用说明</a>获取标准版源码并运行基础控制示例。</li><li>根据开发需求查阅<a href="./../hardware/components.html">硬件参考</a>、<a href="./../examples/">接口示例索引</a>和 <a href="./../advanced/moveit2.html">MoveIt 2</a>。各示例的依赖与验证范围以对应说明为准。</li></ol><h2 id="intelligent" tabindex="-1">H1 智能版 <a class="header-anchor" href="#intelligent" aria-label="Permalink to &quot;H1 智能版 {#intelligent}&quot;">​</a></h2><p>智能版保留 RK3576 主控，并增加 NVIDIA 计算板。两块板卡通过网络连接，开发者可以利用 NVIDIA 计算板部署计算需求较高的应用，在 H1 平台上进行二次开发。</p><p>智能版使用 <strong>原生 Zenoh（<code>rmw_zenoh_cpp</code>）</strong>。两种产品共用开发电脑的 Zenoh 配置；智能版的双板连接、登录及 NVIDIA 计算板使用方法单独说明。</p><p>建议按以下顺序开始：</p><ol><li>按<a href="./intelligent.html">智能版：连接与使用</a>确认双板连接，登录 RK3576 并查询 NVIDIA 计算板的实际地址。</li><li>按<a href="./communication.html#pc-zenoh">开发电脑的 Zenoh 环境</a>配置电脑，完成<a href="./communication.html#verify">通信验证</a>；在 NVIDIA 计算板上运行应用前，另行<a href="./intelligent.html#verify">核对板端通信</a>。</li><li>了解<a href="./../hardware/components.html">器件分布</a>与<a href="./../hardware/robot-model.html">机器人模型</a>，再按应用需求查阅接口参考和<a href="./../example/#按设备版本选择">示例目录</a>。选择示例时，应核对运行位置、通信方式、依赖服务及验证环境。</li><li>需要完整场景应用时，可按<a href="./../example/laundry.html">智能版洗衣服示例</a>准备相机、搭建场景、导入地图，并在 NVIDIA 计算板上部署和验收。</li></ol><h2 id="如何查阅手册" tabindex="-1">如何查阅手册 <a class="header-anchor" href="#如何查阅手册" aria-label="Permalink to &quot;如何查阅手册&quot;">​</a></h2><ul><li><strong>硬件参考、软件接口与高级功能</strong>：查阅机器人能力和 SDK 接口；功能前提以对应页面及设备固件为准。</li><li><strong>系统诊断</strong>：查询固件版本、诊断状态及机内服务。</li><li><strong>应用示例 Example</strong>：查找示例代码、运行说明和接口调用示例。</li><li><strong>常见问题 FAQ</strong>：了解开关机、网络配置、测试工具和日常操作。</li></ul>',15)])])}const f=a(o,[["render",i]]);export{p as __pageData,f as default};
